asrt_round_robin: assert property (@(posedge clk) disable iff (tb_reset)
    (tb_gnt != 0) |->
    let last_grant_index = (last_gnt != 0) ? $onehot0(last_gnt) : 0;
    let start_index = (last_grant_index + 1) % NUM_OF_CLIENTS;
    let expected_gnt = next_req(start_index, tb_req);
    tb_gnt == (1 << expected_gnt)
);

function automatic [tb_num_client_req_width-1:0] next_req(int start, input [NUM_OF_CLIENTS-1:0] req);
    for (int i = start; i < NUM_OF_CLIENTS; i++) begin
        if (req[i]) return i;
    end
    for (int i = 0; i < start; i++) begin
        if (req[i]) return i;
    end
    return 'x;
endfunction

